def polyline(pts, w, c):
    return [line(*a, *b, w, c) for a, b in zip(pts, pts[1:])]


def compass(deg):
    a = math.radians(deg)
    tip = (round(170 + 36 * math.cos(a)), round(100 + 36 * math.sin(a)))
    side = lambda s: (round(170 + 22 * math.cos(a) + s * 8 * math.sin(a)), round(100 + 22 * math.sin(a) - s * 8 * math.cos(a)))
    return [O(170, 100, 52, 52, BR, 16), O(170, 100, 46, 46, CR, 16), star(170, 100, 40, 7, 4, GS),
            line(170, 100, round(170 + 24 * math.cos(a)), round(100 + 24 * math.sin(a)), 6, OR), P([tip, side(1), side(-1)], OR), O(170, 100, 5, 5, IN)]


def plane(x, y, d, c):
    return [R(x - 25, y - 4, 50, 8, c), P([(x - 4 * d, y - 22), (x + 4 * d, y - 22), (x + 8 * d, y + 22), (x - 2 * d, y + 22)], c),
            P([(x - 25 * d, y - 12), (x - 20 * d, y - 12), (x - 16 * d, y + 4), (x - 25 * d, y + 4)], c), P([(x + 25 * d, y - 4), (x + 32 * d, y), (x + 25 * d, y + 4)], c)]


